      gradient.addColorStop(0, "#094851");
      gradient.addColorStop(1, "#f8b46c");
      context.fillStyle = gradient;
      context.fillRect(0, 0, 256, 144);
      context.fillStyle = "#e7fff1";
      context.beginPath();
